ellipse.style:
transform:translate(var(--look-x, 0),var(--look-y, 0));transition:transform .08s ease-out;will-change:transform;svg:not(.active) & {
    @container style(--motion: no-preference) {
      transform: translate(
        calc(-22.52px * var(--parallax, 1)),
        calc(-13px * var(--parallax, 1))
      );
      transition: transform var(--idle-entry-duration)
        cubic-bezier(0.22, 1, 0.36, 1);
      animation: idle-look var(--idle-loop-duration)
        cubic-bezier(0.45, 0.05, 0.55, 0.95) var(--idle-entry-duration)
        infinite;
    }
  };display:inline;fill:#320c23;fill-opacity:1

